      { match: ["api", "issues/5/comments", "--paginate"], attempt: 4, stdout: "[]" },
    ], ["--agent", "atomaton", "--type", "issue"]);
    expect(r.status).not.toBe(0);
    expect(r.ghCalls.some((c) => c.includes("PATCH"))).toBe(false);
